package com.qtekfun.ultimatecamera.core.gpu

import kotlin.math.pow

/**
 * LUTs generated by the project itself (no third-party licence involved, REQ-COL-008). Used by the spike and by the
 * reference-image tests; real camera LUTs are imported by the user or downloaded from the maker (REQ-COL-007).
 */
object SpikeLuts {
    /**
     * A deliberately strong creative grade: filmic S-curve, warm highlights, cool shadows and a little extra
     * saturation, so a broken shader is obvious in the reference images.
     */
    fun creative(size: Int = 33): CubeLut = CubeLut.generate(size, "UltimateCamera spike creative") { r, g, b ->
        val luma = 0.2126f * r + 0.7152f * g + 0.0722f * b
        fun sCurve(v: Float): Float {
            val t = v.coerceIn(0f, 1f)
            return t * t * (3f - 2f * t) * 0.85f + t * 0.15f
        }
        val sat = 1.2f
        val rr = luma + (r - luma) * sat
        val gg = luma + (g - luma) * sat
        val bb = luma + (b - luma) * sat
        val warm = luma.pow(1.5f) * 0.06f
        val cool = (1f - luma).pow(2f) * 0.05f
        Triple(
            sCurve(rr + warm - cool * 0.5f).coerceIn(0f, 1f),
            sCurve(gg).coerceIn(0f, 1f),
            sCurve(bb - warm + cool).coerceIn(0f, 1f)
        )
    }
}
